$extras=[
 ['id'=>'r1','name'=>'Local Thali Tasting (Demo)','category'=>'Restaurant','rating'=>4.6,'cost'=>650,'lat'=>27.6788,'lng'=>84.4365,'description'=>'Demo local food listing.','image'=>$IMG_BOATS],
 ['id'=>'h1','name'=>'Community Homestay (Demo)','category'=>'Homestay','rating'=>4.7,'cost'=>2200,'lat'=>27.5840,'lng'=>84.2600,'description'=>'Demo community stay listing.','image'=>$IMG_FOREST],
 ['id'=>'e1','name'=>'Riverfront Culture Evening (Demo)','category'=>'Event','rating'=>4.5,'cost'=>500,'lat'=>27.6822,'lng'=>84.4252,'description'=>'Demo tourism event marker.','image'=>$IMG_CANOE],
 ['id'=>'b1','name'=>'Handicraft & Gift Walk (Demo)','category'=>'Local Business','rating'=>4.4,'cost'=>500,'lat'=>27.6791,'lng'=>84.4338,'description'=>'Demo small-business discovery marker.','image'=>$IMG_CANOE],
 ['id'=>'x1','name'=>'Travel Assistance Point (Demo)','category'=>'Emergency Service','rating'=>0,'cost'=>0,'lat'=>27.6760,'lng'=>84.4320,'description'=>'Demo marker only — verify official emergency contacts locally.','image'=>$IMG_FOREST],
