<section class="map-shell"><div class="map-sidebar"><div class="d-flex justify-content-between align-items-center mb-2"><div><strong>Explore on Map</strong><div class="small muted">Demo coordinates</div></div><button class="btn btn-sm btn-outline-brand" id="locateMe"><i class="fa-solid fa-location-crosshairs"></i></button></div><input class="form-control mb-2" id="mapSearch" placeholder="Search attractions, food, stays, events..."><select class="form-select" id="mapCategory"><option value="">All categories</option><?php foreach(['Nature','Wildlife','Culture','Food','Adventure','Photography','Family','Shopping','Local Experiences','Restaurant','Homestay','Event','Local Business','Emergency Service'] as $c):?><option><?=$c?></option><?php endforeach;?></select><div class="small muted mt-2">Leaflet + OpenStreetMap • Demo coordinates • no live routing</div></div><div id="mainMap"></div></section>
<script>
const mapPlaces=<?=json_encode($mapItems,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
document.addEventListener('DOMContentLoaded',()=>{const map=L.map('mainMap').setView([27.676,84.43],11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors'}).addTo(map);let markers=[];const colors={'Wildlife':'#176b87','Culture':'#9a6225','Food':'#c15342','Restaurant':'#c15342','Homestay':'#6f57a5','Event':'#d98314','Local Business':'#247a8a','Emergency Service':'#b23b3b'};const iconFor=c=>L.divIcon({className:'',html:`<div style="width:34px;height:34px;border-radius:12px;background:${colors[c]||'#0d5b45'};color:white;display:grid;place-items:center;border:3px solid white;box-shadow:0 5px 12px #0003"><i class="fa-solid fa-location-dot"></i></div>`,iconSize:[34,34],iconAnchor:[17,34]});
function draw(){markers.forEach(m=>map.removeLayer(m));markers=[];const q=document.getElementById('mapSearch').value.toLowerCase(),cat=document.getElementById('mapCategory').value;mapPlaces.filter(p=>(!q||(p.name+' '+p.description).toLowerCase().includes(q))&&(!cat||(p.category===cat||(p.tags||[]).includes(cat)))).forEach(p=>{const details=Number.isInteger(p.id)?`<a href="destination.php?id=${p.id}" class="btn btn-sm btn-brand mt-1">View Details</a>`:`<span class="badge-soft">Prototype marker</span>`;const m=L.marker([p.lat,p.lng],{icon:iconFor(p.category)}).addTo(map).bindPopup(`<div class="map-popup"><img src="${p.image}"><h6 class="mt-2 mb-1">${p.name}</h6><div class="small">${p.category}${p.rating?' • ★ '+p.rating:''}</div><div class="small text-muted my-1">${p.cost?'NPR '+Number(p.cost).toLocaleString():'Demo assistance'}</div>${details}</div>`);markers.push(m)});}
draw();document.getElementById('mapSearch').addEventListener('input',draw);document.getElementById('mapCategory').addEventListener('change',draw);document.getElementById('locateMe').addEventListener('click',()=>navigator.geolocation?navigator.geolocation.getCurrentPosition(pos=>{L.marker([pos.coords.latitude,pos.coords.longitude]).addTo(map).bindPopup('Your current location').openPopup();map.setView([pos.coords.latitude,pos.coords.longitude],13)},()=>BharatpurApp.toast('Location permission was not available')):BharatpurApp.toast('Geolocation is not supported'));const focus=new URLSearchParams(location.search).get('focus');if(focus){const p=mapPlaces.find(x=>String(x.id)===focus);if(p)map.setView([p.lat,p.lng],14)}});
</script>
